// src/components/dashboard/SciChart3DComponent.jsx
import React, { useEffect, useRef, useCallback, useState } from "react";
import { generateUniqueColor } from "../../utils/colors";
import { SciChartReact } from "scichart-react";
import {
  SciChart3DSurface,
  NumericAxis3D,
  Vector3,
  OrbitModifier3D,
  MouseWheelZoomModifier3D,
  PointLineRenderableSeries3D,
  XyzDataSeries3D,
} from "scichart";

// Apply license at module level
SciChart3DSurface.UseCommunityLicense();

// Load WASM at module scope (no function wrapper)
const wasmPromise = SciChart3DSurface.useWasmFromCDN(); // ESLint will not complain here now

const SciChart3DComponent = ({ comparisonData, loading, visibility, setVisibility }) => {
  const sciChartSurfaceRef = useRef(null);
  const wasmContextRef = useRef(null);
  const latestComparisonDataRef = useRef([]);
  const latestVisibilityRef = useRef({});
  const [lastBounds, setLastBounds] = useState(null);

  const fitCameraToBounds = useCallback((sciChart3DSurface, bounds) => {
    if (!sciChart3DSurface || !bounds) return;
    const { minX, maxX, minY, maxY, minZ, maxZ } = bounds;
    const centerX = (minX + maxX) / 2;
    const centerY = (minY + maxY) / 2;
    const centerZ = (minZ + maxZ) / 2;
    const maxSpan = Math.max(maxX - minX, maxY - minY, maxZ - minZ, 1);
    const distanceFactor = 2.0;
    sciChart3DSurface.camera.position = new Vector3(
      centerX - maxSpan * distanceFactor,
      centerY + maxSpan * distanceFactor * 0.8,
      centerZ - maxSpan * distanceFactor
    );
    sciChart3DSurface.camera.target = new Vector3(centerX, centerY, centerZ);
  }, []);

  const renderSeries = useCallback((sciChart3DSurface, wasmContext) => {
    if (!sciChart3DSurface || !wasmContext) return;
    sciChart3DSurface.renderableSeries.clear();

    let minX = Infinity,
      maxX = -Infinity,
      minY = Infinity,
      maxY = -Infinity,
      minZ = Infinity,
      maxZ = -Infinity;

    const compData = latestComparisonDataRef.current || [];
    const vis = latestVisibilityRef.current || {};

    let visibleIndex = 0;
    compData.forEach((throwSession) => {
      if (!vis[throwSession.id]) return;

      const seriesOffsetZ = visibleIndex * 5;
      const lineSeries = new PointLineRenderableSeries3D(wasmContext);
      lineSeries.stroke = generateUniqueColor(throwSession.id);
      lineSeries.strokeThickness = 3;

      const dataSeries = new XyzDataSeries3D(wasmContext);
      (throwSession.trajectory || []).forEach((point) => {
        const x = point.distance;
        const y = point.height;
        const z = seriesOffsetZ;
        dataSeries.append(x, y, z);
        minX = Math.min(minX, x);
        maxX = Math.max(maxX, x);
        minY = Math.min(minY, y);
        maxY = Math.max(maxY, y);
        minZ = Math.min(minZ, z);
        maxZ = Math.max(maxZ, z);
      });

      lineSeries.dataSeries = dataSeries;
      sciChart3DSurface.renderableSeries.add(lineSeries);
      visibleIndex++;
    });

    if (visibleIndex > 0) {
      const bounds = { minX, maxX, minY, maxY, minZ, maxZ };
      setLastBounds(bounds);
      fitCameraToBounds(sciChart3DSurface, bounds);
    }
  }, [fitCameraToBounds]);

  const initChart = useCallback(
    async (rootElement) => {
      const wasmContext = await wasmPromise; // wait for WASM
      wasmContextRef.current = wasmContext;

      const { sciChart3DSurface } = await SciChart3DSurface.create(rootElement, { wasmContext });

      sciChart3DSurface.xAxis = new NumericAxis3D(wasmContext, { axisTitle: "Distance (m)" });
      sciChart3DSurface.yAxis = new NumericAxis3D(wasmContext, { axisTitle: "Height (m)" });
      sciChart3DSurface.zAxis = new NumericAxis3D(wasmContext, { axisTitle: "Throw Comparison" });

      sciChart3DSurface.chartModifiers.add(new OrbitModifier3D());
      sciChart3DSurface.chartModifiers.add(new MouseWheelZoomModifier3D());

      sciChartSurfaceRef.current = sciChart3DSurface;

      renderSeries(sciChart3DSurface, wasmContext);

      return { sciChartSurface: sciChart3DSurface };
    },
    [renderSeries]
  );

  useEffect(() => {
    latestComparisonDataRef.current = comparisonData;
    latestVisibilityRef.current = visibility;
    if (sciChartSurfaceRef.current && wasmContextRef.current) {
      renderSeries(sciChartSurfaceRef.current, wasmContextRef.current);
    }
  }, [comparisonData, visibility, renderSeries]);

  const toggleVisibility = (id) => setVisibility((prev) => ({ ...prev, [id]: !prev[id] }));

  const handleResetCamera = () => {
    if (sciChartSurfaceRef.current && lastBounds) {
      fitCameraToBounds(sciChartSurfaceRef.current, lastBounds);
    }
  };

  if (loading)
    return <div className="bg-white p-6 rounded-xl shadow-lg h-[500px] animate-pulse"></div>;

  if (!comparisonData || comparisonData.length === 0)
    return (
      <div className="bg-white p-6 rounded-xl shadow-lg h-[500px] flex items-center justify-center">
        <p className="text-gray-500">Select one or more throws to see the 3D comparison.</p>
      </div>
    );

  return (
    <div className="bg-white p-6 rounded-xl shadow-lg mt-6 flex flex-col flex-grow h-[calc(100vh-220px)]">
      <h3 className="text-xl font-semibold mb-4 text-gray-800">
        Comparative Throw Trajectory (3D View)
      </h3>
      <div className="flex-1">
        <SciChartReact initChart={initChart} style={{ width: "100%", height: "100%" }} />
      </div>

      <div className="mt-4 flex flex-wrap gap-3 items-center">
        {comparisonData.map((session) => (
          <button
            key={session.id}
            onClick={() => toggleVisibility(session.id)}
            className={`flex items-center space-x-2 px-3 py-1 rounded-full text-sm font-medium border transition ${
              visibility[session.id] ? "bg-gray-100 border-gray-300" : "bg-gray-200 border-gray-400 opacity-50"
            }`}
          >
            <span className="w-4 h-4 rounded-full" style={{ backgroundColor: generateUniqueColor(session.id) }} />
            <span>{session.id}</span>
          </button>
        ))}

        {lastBounds && (
          <button
            onClick={handleResetCamera}
            className="ml-auto px-4 py-1.5 bg-primary-500 text-white rounded-full text-sm font-medium hover:bg-primary-600 transition"
          >
            Reset Camera
          </button>
        )}
      </div>
    </div>
  );
};

export default SciChart3DComponent;
